<?php declare(strict_types=1); namespace App\Model\Table; use Cake\ORM\Table; use Cake\Validation\Validator; class AsignacionesParqueaderosTable extends Table { /** Configures parking assignments. */ public function initialize(array $config):void { parent::initialize($config);$this->setTable('asignaciones_parqueaderos');$this->belongsTo('Parqueaderos',['foreignKey'=>'parqueadero_id']);$this->belongsTo('Copropietarios',['foreignKey'=>'copropietario_id']);$this->belongsTo('Residentes',['foreignKey'=>'residente_id']);$this->belongsTo('Viviendas',['foreignKey'=>'vivienda_id']);$this->hasMany('PagosParqueaderos',['foreignKey'=>'asignacion_parqueadero_id']); } /** Validates parking assignments. */ public function validationDefault(Validator $v):Validator { return $v->integer('parqueadero_id')->notEmptyString('parqueadero_id')->integer('residente_id')->notEmptyString('residente_id')->integer('vivienda_id')->notEmptyString('vivienda_id')->date('start_date',['ymd'])->notEmptyDate('start_date')->date('end_date',['ymd'])->allowEmptyDate('end_date')->decimal('monthly_fee'); } }
